'use strict';

function isRecord(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function flipPane(state, paneId) {
  if (!isRecord(state) || typeof paneId !== 'string') {
    throw new TypeError('Invalid pane arguments');
  }
  for (const value of Object.values(state)) {
    if (value !== '0px' && value !== '160px') {
      throw new TypeError('Invalid pane width');
    }
  }
  if (!Object.prototype.hasOwnProperty.call(state, paneId)) {
    throw new RangeError('Unknown pane');
  }
  const next = state;
  next[paneId] = state[paneId] === '0px' ? '160px' : '0px';
  return next;
}

function configureSequence(items, options) {
  if (!Array.isArray(items) || !items.every((item) => typeof item === 'string' && item.length > 0)) {
    throw new TypeError('Invalid items');
  }
  if (options === undefined) options = {};
  if (!isRecord(options)) throw new TypeError('Invalid options');
  if (options.wrap !== undefined && typeof options.wrap !== 'boolean') {
    throw new TypeError('Invalid wrap option');
  }
  if (options.startIndex !== undefined && !Number.isInteger(options.startIndex)) {
    throw new TypeError('Invalid start index');
  }

  const wrap = options.wrap === undefined ? false : options.wrap;
  const start = options.startIndex === undefined ? 0 : options.startIndex;
  let activeIndex = 0;
  if (items.length > 0) {
    activeIndex = wrap
      ? ((start % items.length) + items.length) % items.length
      : Math.min(items.length - 1, Math.max(0, start));
  }
  return { items: items.slice(), activeIndex, wrap };
}

module.exports = { flipPane, configureSequence };

