'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api).sort(), ['configureSequence', 'flipPane']);
const { flipPane, configureSequence } = api;

const state = { left: '0px', right: '160px' };
const stateSnapshot = { ...state };
const flipped = flipPane(state, 'left');
assert.deepStrictEqual(flipped, { left: '160px', right: '160px' });
assert.deepStrictEqual(state, stateSnapshot);
assert.notStrictEqual(flipped, state);
assert.deepStrictEqual(flipPane(state, 'right'), { left: '0px', right: '0px' });
assert.throws(() => flipPane(null, 'left'), TypeError);
assert.throws(() => flipPane([], 'left'), TypeError);
assert.throws(() => flipPane({ left: '10px' }, 'left'), TypeError);
assert.throws(() => flipPane({ left: '0px' }, 1), TypeError);
assert.throws(() => flipPane({ left: '0px' }, 'missing'), RangeError);
const inherited = Object.create({ inherited: '0px' });
inherited.own = '160px';
assert.throws(() => flipPane(inherited, 'inherited'), RangeError);

const sourceItems = ['alpha', 'beta', 'gamma'];
const options = { startIndex: 8, wrap: false };
const configured = configureSequence(sourceItems, options);
assert.deepStrictEqual(configured, { items: ['alpha', 'beta', 'gamma'], activeIndex: 2, wrap: false });
assert.notStrictEqual(configured.items, sourceItems);
assert.deepStrictEqual(sourceItems, ['alpha', 'beta', 'gamma']);
assert.deepStrictEqual(options, { startIndex: 8, wrap: false });
configured.items.push('delta');
assert.deepStrictEqual(sourceItems, ['alpha', 'beta', 'gamma']);
assert.deepStrictEqual(configureSequence(['a', 'b', 'c'], { startIndex: -1, wrap: true }), { items: ['a', 'b', 'c'], activeIndex: 2, wrap: true });
assert.deepStrictEqual(configureSequence(['a', 'b', 'c'], { startIndex: 7, wrap: true }), { items: ['a', 'b', 'c'], activeIndex: 1, wrap: true });
assert.deepStrictEqual(configureSequence(['a', 'b'], { startIndex: -20 }), { items: ['a', 'b'], activeIndex: 0, wrap: false });
assert.deepStrictEqual(configureSequence([]), { items: [], activeIndex: 0, wrap: false });
assert.deepStrictEqual(configureSequence([], { startIndex: -99, wrap: true }), { items: [], activeIndex: 0, wrap: true });
for (const bad of [null, {}, 'x', [1], [''], ['ok', '']]) assert.throws(() => configureSequence(bad), TypeError);
for (const badOptions of [null, [], 'x', { wrap: 1 }, { startIndex: 1.2 }, { startIndex: NaN }, { startIndex: Infinity }]) assert.throws(() => configureSequence(['a'], badOptions), TypeError);

